export function addMemberEventAccessControls(article,member){
 const actions=document.createElement('div');actions.className='garage-page-actions';
 const invite=document.createElement('button'),revoke=document.createElement('button'),message=document.createElement('p');invite.type=revoke.type='button';invite.textContent='Enlace personal para apuntarse a eventos';revoke.textContent='Revocar acceso personal a eventos';message.setAttribute('role','status');
 const request=async action=>{const r=await fetch('/api/club/member-access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,memberId:member.id})});const data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo completar la operación.');return data;};
 invite.onclick=async()=>{invite.disabled=true;try{const data=await request('invite'),dialog=document.createElement('dialog');dialog.className='member-event-access-dialog';const heading=document.createElement('h2');heading.textContent='Acceso personal de '+member.pilot;const p=document.createElement('p');p.textContent='Entrégale este enlace en privado. Permite apuntarse a eventos solo con su ficha. Caduca en siete días y se activa una sola vez; no concede administración.';const input=document.createElement('input');input.readOnly=true;input.value=new URL(data.activationPath,location.href).href;input.setAttribute('aria-label','Enlace personal del socio');const copy=document.createElement('button'),close=document.createElement('button');copy.textContent='Copiar enlace privado';close.textContent='Cerrar';copy.type=close.type='button';copy.onclick=async()=>{try{await navigator.clipboard.writeText(input.value);copy.textContent='Copiado';}catch{input.focus();input.select();}};close.onclick=()=>dialog.close();dialog.append(heading,p,input,copy,close);document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();}catch(error){message.textContent=error.message;}finally{invite.disabled=false;}};
 revoke.onclick=async()=>{if(!confirm('¿Cerrar el acceso personal de este socio en todos sus dispositivos? Sus inscripciones se conservarán.'))return;revoke.disabled=true;try{await request('revoke');message.textContent='Acceso personal revocado.';}catch(error){message.textContent=error.message;}finally{revoke.disabled=false;}};
 actions.append(invite,revoke);article.append(actions,message);
}
